{
  "name": "nagara-spike-ldr-api",
  "main": "src/index.ts",
  "compatibility_date": "2026-09-01",
  "compatibility_flags": ["nodejs_compat"],
  "d1_databases": [
    { "binding": "DB", "database_name": "nagara-spike-ldr-db", "database_id": "local-only", "migrations_dir": "migrations" }
  ],
  "r2_buckets": [{ "binding": "BUCKET", "bucket_name": "nagara-spike-ldr-bucket" }],
  "workflows": [
    {
      "name": "nagara-spike-ldr-extraction",
      "binding": "EXTRACTION",
      "class_name": "ExtractionWorkflow",
      "script_name": "nagara-spike-ldr-pipeline"
    }
  ],
  "services": [{ "binding": "PIPELINE", "service": "nagara-spike-ldr-pipeline" }]
}
interface Env {
  DB: D1Database;
  BUCKET: R2Bucket;
  EXTRACTION: Workflow;
  PIPELINE: Fetcher;
}

interface StartBody {
  id: string;
  url: string;
  domain: string;
  html: string;
  recipe?: string;
}

const json = (body: unknown, status = 200) => Response.json(body, { status });

const start = async (env: Env, body: StartBody) => {
  await env.DB.prepare("INSERT INTO items (id, url, domain, status, created_at) VALUES (?, ?, ?, 'queued', ?)")
    .bind(body.id, body.url, body.domain, Date.now())
    .run();

  const instance = await env.EXTRACTION.create({
    id: body.id,
    params: { html: body.html, recipe: body.recipe, domain: body.domain },
  });

  return json({ id: instance.id }, 201);
};

// Reading the status settles the item: a complete instance's output lands in
// R2 and the row flips, so D1 and R2 are written by this Worker and the
// persisted state is visible to whoever shares --persist-to.
const read = async (env: Env, id: string) => {
  const instance = await env.EXTRACTION.get(id);
  const status = await instance.status();
  const row = await env.DB.prepare("SELECT * FROM items WHERE id = ?").bind(id).first<{ status: string }>();

  if (status.status === "complete" && row != null && row.status === "queued") {
    const output = status.output as { state: string; title?: string; units?: unknown[]; recipe?: string };

    await env.BUCKET.put(`items/${id}/output.json`, JSON.stringify(output));
    await env.DB.prepare("UPDATE items SET status = ?, title = ?, unit_count = ?, finished_at = ? WHERE id = ?")
      .bind(output.state, output.title ?? null, output.units?.length ?? null, Date.now(), id)
      .run();
  }

  const { __LOCAL_DEV_STEP_OUTPUTS: steps, ...rest } = status as Record<string, unknown>;

  return json({
    workflow: rest,
    stepNames: steps == null ? null : Object.keys(steps as object),
    row: await env.DB.prepare("SELECT * FROM items WHERE id = ?").bind(id).first(),
  });
};

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const match = url.pathname.match(/^\/items\/([\w-]+)(\/output)?$/);

    if (request.method === "POST" && url.pathname === "/items") {
      return await start(env, await request.json<StartBody>());
    }

    if (request.method === "GET" && match != null && match[2] != null) {
      const object = await env.BUCKET.get(`items/${match[1]}/output.json`);

      return object == null ? json({ error: "no output" }, 404) : new Response(object.body);
    }

    if (request.method === "GET" && match != null) {
      return await read(env, match[1]);
    }

    // The pipeline has no public port in multi-config mode, so its own routes
    // are reached through the service binding.
    if (url.pathname.startsWith("/pipeline/")) {
      return await env.PIPELINE.fetch(new Request(new URL(url.pathname.slice("/pipeline".length), url), request));
    }

    return new Response("not found", { status: 404 });
  },
};
{
  "$schema": "node_modules/wrangler/config-schema.json",
  "name": "nagara-spike-ldr-pipeline",
  "compatibility_date": "2026-09-01",
  "compatibility_flags": ["nodejs_compat"],
  "worker_loaders": [{ "binding": "LOADER" }],
  "workflows": [
    { "name": "nagara-spike-ldr-extraction", "binding": "EXTRACTION", "class_name": "ExtractionWorkflow" }
  ],
  "durable_objects": {
    "bindings": [
      { "name": "DOMAIN_QUEUE", "class_name": "DomainQueue" },
      { "name": "JOB_INDEX", "class_name": "JobIndex" }
    ]
  },
  "migrations": [
    { "tag": "v1", "new_sqlite_classes": ["DomainQueue", "JobIndex"] },
    { "tag": "flue-class-FlueAuthorAgent", "new_sqlite_classes": ["FlueAuthorAgent"] },
    { "tag": "flue-class-FlueRevisorAgent", "new_sqlite_classes": ["FlueRevisorAgent"] }
  ],
  "vars": {
    "agentModel": "cloudflare-ai-gateway/workers-ai/@cf/zai-org/glm-5.3-flash",
    "CLOUDFLARE_ACCOUNT_ID": "2b32439a1d8fdcdf00a9f7f654a11a6d",
    "CLOUDFLARE_GATEWAY_ID": "nagara",
    "agentMaxTurns": 100,
    "authoringRetries": 1,
    "revisionRetries": 2,
    "leaseAlarmMs": 60000,
    "indexSweepMs": 86400000,
    "recipeCpuMs": 2000,
    "maxHtmlBytes": 1048576
  }
}
#!/usr/bin/env bash
# usage: fetch.sh <url> <out.json>; reads the Firecrawl key from api/.env without echoing it
set -euo pipefail
KEY=$(grep '^NAGARA_FIRECRAWL_API_KEY='REDACTED'"')
curl -s -X POST https://api.firecrawl.dev/v2/scrape -H "Authorization: Bearer $KEY" -H content-type:application/json \
  -d "{\"url\":\"$1\",\"formats\":[\"rawHtml\"],\"proxy\":\"auto\"}" -o "$2"

