import json, sys, time, urllib.request
B = "/home/agus/workspace/asermax/nagara/.scratch/cloudflare-migration/spikes/local-dev-b/articles/"
id_, kind = sys.argv[1], sys.argv[2]
timeout = float(sys.argv[3]) if len(sys.argv) > 3 else 300
body = json.load(open(B + "body-author.json"))
body["id"] = id_
if kind == "recipe":
    body["recipe"] = open(B + "recipe.js").read()
t0 = time.time()
req = urllib.request.Request("http://localhost:8821/items", data=json.dumps(body).encode(), headers={"content-type": "application/json"})
try:
    r = urllib.request.urlopen(req, timeout=60)
    print("POST", r.status, r.read().decode()[:300], f"{time.time()-t0:.2f}s")
except urllib.error.HTTPError as e:
    print("POST", e.code, e.read().decode()[:600], f"{time.time()-t0:.2f}s"); sys.exit(1)
except Exception as e:
    print("POST error", repr(e), f"{time.time()-t0:.2f}s"); sys.exit(1)
last = None
while time.time() - t0 < timeout:
    try:
        r = urllib.request.urlopen(f"http://localhost:8821/items/{id_}", timeout=30)
        d = json.loads(r.read())
        st = d["workflow"].get("status")
    except urllib.error.HTTPError as e:
        d, st = None, f"HTTP {e.code}: {e.read().decode()[:200]}"
    except Exception as e:
        d, st = None, repr(e)
    if st != last:
        print(f"{time.time()-t0:7.2f}s status={st} steps={d and d['stepNames']}", flush=True); last = st
    if st in ("complete", "errored", "terminated"):
        break
    time.sleep(1)
print(f"done {time.time()-t0:.2f}s")
if d:
    out = d["workflow"].get("output") or {}
    units = out.get("units") or []
    kinds = {}
    for u in units: kinds[u.get("kind")] = kinds.get(u.get("kind"), 0) + 1
    print("state", out.get("state"), "title", out.get("title"), "units", len(units), kinds, "error", d["workflow"].get("error"))
    print("row", d["row"])
    if out.get("recipe"): open(B + f"recipe-{id_}.js", "w").write(out["recipe"])
EOF
